import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

kernel_pass = verify('gpu_kernel_contracts_pass', '''
    use core.gpu;
    kernel fn copy(input: GpuSlice<f32>, output: GpuSlice<f32>, n: i32) -> void {
        gpu.barrier();
        let i = gpu.global_id_x();
        if i < n {
            output[i] = input[i];
        }
    }
    host fn main() -> i32 {
        let dev = gpu.default_device()
        let input = gpu.alloc_f32(dev, 8)
        let output = gpu.alloc_f32(dev, 8)
        let input_view = gpu.slice(input, 0, 8)
        let output_view = gpu.slice(output, 0, 8)
        let event = gpu.launch3(copy, 1, 8, input_view, output_view, 8)
        gpu.wait(event)
        discard input_view
        discard output_view
        gpu.free(input)
        gpu.free(output)
        return 0
    }
''', 0)
assert kernel_pass['errors'] == 0, kernel_pass
assert not any('aliases GpuSlice parameters' in message for message in messages(kernel_pass)), kernel_pass
assert not any('gpu.barrier' in message and 'divergent control flow' in message for message in messages(kernel_pass)), kernel_pass

aliased_launch = verify('gpu_kernel_launch_alias', '''
    use core.gpu;
    kernel fn copy(input: GpuSlice<f32>, output: GpuSlice<f32>) -> void {
        let i = gpu.global_id_x();
        output[i] = input[i];
    }
    host fn main() -> i32 {
        let dev = gpu.default_device()
        let buffer = gpu.alloc_f32(dev, 8)
        let view = gpu.slice(buffer, 0, 8)
        let event = gpu.launch2(copy, 1, 8, view, view)
        gpu.wait(event)
        discard view
        gpu.free(buffer)
        return 0
    }
''', 1)
assert any('host function `main` launch `copy` via `gpu.launch2` aliases GpuSlice parameters `input` and `output` through owner `buffer`' in message for message in messages(aliased_launch)), aliased_launch

branch_barrier = verify('gpu_kernel_branch_barrier', '''
    use core.gpu;
    kernel fn bad(output: GpuSlice<f32>, n: i32) -> void {
        let i = gpu.global_id_x();
        if i < n {
            gpu.barrier();
            output[i] = 1.0;
        }
    }
    host fn main() -> i32 {
        return 0
    }
''', 1)
assert any('kernel function `bad` cannot use `gpu.barrier` inside divergent control flow' in message for message in messages(branch_barrier)), branch_barrier

helper_barrier = verify('gpu_kernel_helper_barrier', '''
    use core.gpu;
    device fn sync_point() -> void {
        gpu.barrier();
    }
    kernel fn bad(output: GpuSlice<f32>, n: i32) -> void {
        let i = gpu.global_id_x();
        if i < n {
            sync_point();
            output[i] = 1.0;
        }
    }
    host fn main() -> i32 {
        return 0
    }
''', 1)
assert any('kernel function `bad` cannot call barrier-carrying function `sync_point` inside divergent control flow' in message for message in messages(helper_barrier)), helper_barrier

print('compiler-gpu-kernel-contracts-ok')

